using System;
using System.Collections.Generic;
using System.Text;
using UnityEngine;

namespace FPS
{
    /// <summary>
    /// A modular weapon (Resources/Weapons): the Blender model (Assets/_Game/Art/Weapons/Models, see weapons_manifest.json)
    /// with its sockets, the attachment slots (allowed attachments, default) and the moving parts. Linked to its
    /// WeaponCatalog entry (stats, menu card, bots) by <see cref="weaponName"/>. WeaponAttachments assembles it on a
    /// WeaponController; generated by Tools > FPS > Weapons > Build Weapon Data (from the manifest).
    /// </summary>
    [CreateAssetMenu(menuName = "FPS/Weapon Data", fileName = "Weapon")]
    public class WeaponData : ScriptableObject
    {
        [Serializable]
        public class Slot
        {
            public AttachmentSlot slot;
            [Tooltip("Socket transform on the model")] public string socket;
            [Tooltip("Model part the attachment rides on (Glock optic: Slide); empty = the socket")] public string parentPart;
            [Tooltip("The weapon can't do without it (M700 has no iron sights): no 'none' choice")] public bool required;
            public AttachmentData defaultAttachment;
            public AttachmentData[] allowed = new AttachmentData[0];

            public AttachmentData Allowed(string id)
            {
                if (string.IsNullOrEmpty(id)) return null;
                foreach (var a in allowed) if (a && a.id == id) return a;
                return null;
            }
        }

        [Tooltip("WeaponCatalog name")] public string weaponName;
        [Tooltip("weapons_manifest.json id")] public string modelId;
        public GameObject model;
        public Slot[] slots = new Slot[0];

        [Header("Moving parts")]
        [Tooltip("Mesh pulled back by the reload / bolt cycle (Bolt, Slide)")] public string boltPart = "Bolt";
        [Tooltip("Pistol: the slide cycles on every shot (WeaponController.bolt)")] public bool slideCycles;
        [Tooltip("The charging handle rides the bolt carrier on every shot (AK, M14)")] public bool boltReciprocates;
        [Tooltip("Reload / bolt pull distance (m)")] public float boltTravel = 0.085f;
        [Tooltip("Per-shot travel of the cycling part (m)")] public float cycleTravel = 0.035f;
        [Tooltip("Bolt action: the handle is lifted this many degrees about the bore before it is pulled")] public float boltLiftAngle;

        [Header("View")]
        [Tooltip("Muzzle flash size (1 = rifle)")] public float flashScale = 1f;
        [Tooltip("Uniform scale of the model and everything mounted on it (set by the builder, WeaponSpecs.scale): the imported " +
                 "real-size models read small in the hands next to the generated ones, so they are drawn a little bigger")]
        public float modelScale = 1f;
        [Tooltip("Added to the archetype hip position (camera space, m)")] public Vector3 hipOffset;
        [Tooltip("Single-round loading: material of the cartridge in the support hand")] public Material shellMaterial;
        public float shellLength = 0.071f, shellDiameter = 0.012f;
        [Tooltip("Magazine capacity of the model (manifest)")] public int capacity;

        public Slot GetSlot(AttachmentSlot s)
        {
            foreach (var x in slots) if (x != null && x.slot == s) return x;
            return null;
        }

        public int SlotIndex(AttachmentSlot s)
        {
            for (int i = 0; i < slots.Length; i++) if (slots[i] != null && slots[i].slot == s) return i;
            return -1;
        }
    }

    /// <summary>Lookup of the weapon / attachment data assets and the player's attachment choice.</summary>
    public static class WeaponDataDB
    {
        public const string ResourcesFolder = "Weapons";
        static WeaponData[] weapons;
        static AttachmentData[] attachments;

        static void Load()
        {
            if (weapons != null) return;
            weapons = Resources.LoadAll<WeaponData>(ResourcesFolder);
            attachments = Resources.LoadAll<AttachmentData>(ResourcesFolder);
        }

        /// <summary>Forget the loaded assets (editor: after the builder changed them).</summary>
        public static void Clear() { weapons = null; attachments = null; }

        public static WeaponData[] Weapons { get { Load(); return weapons; } }
        public static AttachmentData[] Attachments { get { Load(); return attachments; } }

        public static WeaponData Get(string weaponName)
        {
            if (string.IsNullOrEmpty(weaponName)) return null;
            Load();
            foreach (var d in weapons) if (d && d.weaponName == weaponName) return d;
            return null;
        }

        public static AttachmentData Attachment(string id)
        {
            if (string.IsNullOrEmpty(id)) return null;
            Load();
            foreach (var a in attachments) if (a && a.id == id) return a;
            return null;
        }

        /// <summary>Attachment per slot (WeaponData.slots order): the player's saved choice, else the slot default.</summary>
        public static AttachmentData[] Selection(WeaponData d)
        {
            if (!d) return new AttachmentData[0];
            var sel = new AttachmentData[d.slots.Length];
            for (int i = 0; i < d.slots.Length; i++) sel[i] = Chosen(d, d.slots[i]);
            return sel;
        }

        /// <summary>The attachment the player chose for a slot (saved id → allowed attachment; "" = none; unset = default).</summary>
        public static AttachmentData Chosen(WeaponData d, WeaponData.Slot s)
        {
            if (!d || s == null) return null;
            string saved = PlayerLoadout.GetAttachment(d.weaponName, s.slot.ToString());
            if (saved == null) return s.defaultAttachment;
            if (saved.Length == 0) return s.required ? s.defaultAttachment : null;
            var a = s.Allowed(saved);
            return a ? a : s.defaultAttachment;
        }

        /// <summary>Compact text of a selection (change detection: what is mounted vs what was chosen).</summary>
        public static string Signature(AttachmentData[] sel)
        {
            if (sel == null || sel.Length == 0) return "";
            var sb = new StringBuilder();
            for (int i = 0; i < sel.Length; i++)
            {
                if (i > 0) sb.Append('|');
                if (sel[i]) sb.Append(sel[i].id);
            }
            return sb.ToString();
        }

        /// <summary>Signature of the player's current choice for a weapon ("" when it has no attachment data).</summary>
        public static string ChoiceSignature(string weaponName)
        {
            var d = Get(weaponName);
            return d ? Signature(Selection(d)) : "";
        }

        // ------------------------------------------------------------------ menu texts

        public static string SlotName(AttachmentSlot s) => s switch
        {
            AttachmentSlot.Optic => "Прицел",
            AttachmentSlot.Muzzle => "Дульное устройство",
            AttachmentSlot.Underbarrel => "Под стволом",
            AttachmentSlot.Side => "Боковая планка",
            AttachmentSlot.Magazine => "Магазин",
            _ => s.ToString(),
        };

        /// <summary>Name of the "nothing mounted" choice of a slot.</summary>
        public static string NoneName(WeaponData d, WeaponData.Slot s)
        {
            switch (s.slot)
            {
                case AttachmentSlot.Optic: return "Механический";
                case AttachmentSlot.Magazine:
                    var def = d ? WeaponCatalog.Get(d.weaponName) : null;
                    return "Стандартный" + (def != null ? " (" + def.mag + ")" : "");
                default: return "Нет";
            }
        }

        /// <summary>The selection as one line of names ("Голографический · Пламегаситель"), empty slots skipped.</summary>
        public static string Summary(WeaponData d)
        {
            if (!d) return "";
            var parts = new List<string>();
            foreach (var a in Selection(d)) if (a) parts.Add(a.Name);
            return parts.Count > 0 ? string.Join(" · ", parts) : "без модулей";
        }

        /// <summary>Stat changes of an attachment as rich text lines (green = better, red = worse).</summary>
        public static string Effects(AttachmentData a)
        {
            if (!a) return "";
            var sb = new StringBuilder();
            void Line(string text, bool good) => sb.Append("<color=").Append(good ? "#73E680" : "#FF6B5C").Append('>').Append(text).Append("</color>\n");
            void Pct(string what, float mul, bool lowerIsBetter)
            {
                if (Mathf.Abs(mul - 1f) < 0.005f) return;
                int p = Mathf.RoundToInt((mul - 1f) * 100f);
                Line(what + " " + (p > 0 ? "+" : "−") + Mathf.Abs(p) + "%", lowerIsBetter ? p < 0 : p > 0);
            }
            if (a.magnification > 1.01f) Line("Увеличение " + a.magnification.ToString("0.#") + "×", true);
            if (a.scoped) Line("Снайперский прицел на весь экран", true);
            else if (a.opaqueSightLine) Line("Прицельная сетка на весь экран", true);
            if (a.suppressed) Line("Тихий выстрел: без вспышки света, боты слышат хуже", true);
            if (a.magCapacity > 0) Line("Ёмкость " + a.magCapacity + " патронов", true);
            if (a.laser) Line("Лазерный целеуказатель (" + GameSettings.KeyName(BindAction.Laser) + ")", true);
            if (a.flashlight) Line("Фонарь (держать " + GameSettings.KeyName(BindAction.Melee) + ")", true);
            if (a.foregrip) Line("Удобный хват для второй руки", true);
            Pct("Отдача", a.recoilMul, true);
            Pct("Разброс от бедра", a.hipSpreadMul, true);
            Pct("Разброс в прицеле", a.adsSpreadMul, true);
            Pct("Время прицеливания", a.adsTimeMul, true);
            Pct("Перезарядка", a.reloadTimeMul, true);
            Pct("Скорость передвижения", a.moveSpeedMul, false);
            Pct("Дальность", a.rangeMul, false);
            Pct("Урон", a.damageMul, false);
            Pct("Вспышка", a.flashMul, true);
            Pct("Громкость", a.volumeMul, true);
            return sb.ToString().TrimEnd('\n');
        }
    }
}
